	offset, _, _ := WFS.ReadFile(ctx, zoneId, "c1")
	if offset != 12 {
		t.Errorf("offset mismatch: expected 12, got %d", offset)
	}
	err = WFS.AppendData(ctx, zoneId, "c1", []byte(" world"))
	if err != nil {
		t.Fatalf("error appending data: %v", err)
