	err = withLock(WFS, zoneId, "c1", func(entry *CacheEntry) error {
		if entry == nil {
			return fmt.Errorf("entry not found")
		}
		if len(entry.DataEntries) != 1 {
			return fmt.Errorf("data entries mismatch: expected 1, got %d", len(entry.DataEntries))
		}
