        if response.status_code != httpx.codes.OK:
            logger.error(f"Failed to send telemetry data: {response.status_code} {response.text}")
        else:
            logger.debug("Telemetry data sent successfully.")
    except httpx.HTTPStatusError:
        logger.exception("HTTP error occurred")
    except httpx.RequestError:
        logger.exception("Request error occurred")
    except Exception:  # noqa: BLE001
        logger.exception("Unexpected error occurred")

def _set_span_status(self, current_span: Span, error: Exception | None = None):
    """Sets the status and attributes of the current span based on the presence of an error."""
    if error:
        error_string = self._error_to_string(error)
        current_span.set_status(Status(StatusCode.ERROR, error_string))
        current_span.set_attribute("error.message", error_string)

        if isinstance(error, Exception):
            current_span.record_exception(error)
        else:
            exception_type = error.__class__.__name__
            exception_message = str(error)
            if not exception_message:
                exception_message = repr(error)
            attributes: dict[str, AttributeValue] = {
                OTELSpanAttributes.EXCEPTION_TYPE: exception_type,
                OTELSpanAttributes.EXCEPTION_MESSAGE: exception_message,
                OTELSpanAttributes.EXCEPTION_ESCAPED: False,
                OTELSpanAttributes.EXCEPTION_STACKTRACE: error_string,
            }
            current_span.add_event(name="exception", attributes=attributes)
    else:
        current_span.set_status(Status(StatusCode.OK))

def end(
    self,
    inputs: dict[str, Any],
    outputs: dict[str, Any],
    error: Exception | None = None,
    metadata: dict[str, Any] | None = None,
) -> None:
    if not self._ready:
        return
    self.trace.root_span.end(
        input=self._convert_to_langwatch_types(inputs),
        output=self._convert_to_langwatch_types(outputs),
        error=error,
    )

    if metadata and "flow_name" in metadata:
        self.trace.update(metadata=(self.trace.metadata or {}) | {"labels": [f"Flow: {metadata['flow_name']}"]})

    if self.trace.api_key or self._client.api_key:
        self.trace.deferred_send_spans()

async def _cancel_task(self, task: asyncio.Task, cancel_msg: str) -> None:
    task.cancel(cancel_msg)
    try:
        await task
    except asyncio.CancelledError:
        current_task = asyncio.current_task()
        if sys.version_info >= (3, 11):
            if current_task and current_task.cancelling() > 0:
                raise
        elif current_task and hasattr(current_task, "_must_cancel") and current_task._must_cancel:
            raise

